<?php require 'includes/db.php';require 'includes/helpers.php';require_login();$msg='';if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM loans WHERE id=? AND user_id=?")->execute([(int)$_GET['delete'],user_id()]);header('Location:loans.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$principal=(float)$_POST['principal'];$remaining=(float)$_POST['remaining'];$interest=(float)$_POST['interest'];$emi=(float)$_POST['emi'];$day=(int)$_POST['due_day'];if($name&&$principal>0&&$emi>0){$pdo->prepare("INSERT INTO loans(user_id,name,principal,remaining,interest,emi,due_day) VALUES(?,?,?,?,?,?,?)")->execute([user_id(),$name,$principal,$remaining,$interest,$emi,$day]);$msg='Loan added.';}}$s=$pdo->prepare("SELECT * FROM loans WHERE user_id=? ORDER BY id DESC");$s->execute([user_id()]);$loans=$s->fetchAll(PDO::FETCH_ASSOC);?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Loans & EMI</title><link rel="stylesheet" href="assets/style.css"></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Loans & EMI</h1><p>Keep your loan commitments in one place</p></div></header><div class="panel" style="max-width:900px"><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form method="post" class="formgrid"><label>Loan name<input name="name" placeholder="Personal Loan" required></label><label>Original principal<input name="principal" type="number" step=".01" min=".01" required></label><label>Remaining amount<input name="remaining" type="number" step=".01" min="0" required></label><label>Interest %<input name="interest" type="number" step=".01" min="0" value="0"></label><label>Monthly EMI<input name="emi" type="number" step=".01" min=".01" required></label><label>Due day<input name="due_day" type="number" min="1" max="31" value="5"></label><div class="full actions"><button class="btn primary">Add Loan</button></div></form></div><div class="kpi-row"><?php $total=0;$emis=0;foreach($loans as $l){$total+=$l['remaining'];$emis+=$l['emi'];}?><div class="card"><div class="mini">Total remaining</div><div class="big expense">₹<?=money($total)?></div></div><div class="card"><div class="mini">Monthly EMI</div><div class="big">₹<?=money($emis)?></div></div><div class="card"><div class="mini">Loans</div><div class="big"><?=count($loans)?></div></div></div><div class="cat-grid"><?php foreach($loans as $l):?><div class="cat" style="display:block"><div style="display:flex;justify-content:space-between"><b><?=h($l['name'])?></b><a class="delete" href="?delete=<?=$l['id']?>" onclick="return confirm('Delete this loan?')">Delete</a></div><div class="goal"><div class="goal-top"><span>Remaining</span><b>₹<?=money($l['remaining'])?></b></div><div class="bar"><span style="width:<?=min(100,$l['remaining']/$l['principal']*100)?>%"></span></div></div><small>EMI ₹<?=money($l['emi'])?> · Due day <?=$l['due_day']?> · <?=$l['interest']?>% interest</small></div><?php endforeach;?></div></main></div></body></html>